CREATE TABLE "public"."dialects" (
  "id"                 integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name"               text    NOT NULL,
  "region_description" text,
  CONSTRAINT "dialects_name_key" UNIQUE (name),
  CONSTRAINT "dialects_pkey" PRIMARY KEY (id)
);

REVOKE ALL ON SEQUENCE "public"."dialects_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."dialects_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."dialects_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."dialects_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."dialects_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."dialects_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."dialects_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."dialects_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."dialects" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."dialects" TO "service_role";

REVOKE ALL ON TABLE "public"."dialects" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."dialects" TO "postgres";
